/* Lyham Life — lisa.js : lettres de Lisa (anglais + aide en français), choix de réponse, progression linguistique */
(function () {
  'use strict';
  var LL = window.LyhamLife;
  /* r : [anglais, français, effet lien, drapeau optionnel, remarque linguistique optionnelle] — la 1re réponse est toujours la plus naturelle (l'ordre est mélangé à l'affichage) */
  var L = [
    { t: 'Hello from Wellbrook!', lv: 'A1', en: 'Hello Lyham! My name is Lisa. I am fourteen and I live in Wellbrook, a small town north of London. I have a dog. His name is Biscuit. I like drawing and swimming. What about you? Have you got a pet?', fr: 'Bonjour Lyham ! Je m\'appelle Lisa. J\'ai quatorze ans et j\'habite à Wellbrook, une petite ville au nord de Londres. J\'ai un chien qui s\'appelle Biscuit. J\'aime dessiner et nager. Et toi ? As-tu un animal ?',
      r: [['Hi Lisa! Yes, I have got a ginger cat. His name is Moka and he loves his red ball.', 'Salut Lisa ! Oui, j\'ai un chat roux. Il s\'appelle Moka et il adore sa balle rouge.', 4, 'lisa_moka'], ['Hello. I have a cat.', 'Bonjour. J\'ai un chat.', 1], ['Hello, I am Lyham and I have 13 years.', 'Bonjour, je suis Lyham et j\'ai 13 ans.', 0, null, 'En anglais on dit « I am 13 (years old) » : on utilise « be », pas « have » !']] },
    { t: 'My family', lv: 'A1', en: 'Thank you for your letter! I live with my mum, my dad and my little brother, Harry. He is seven and he is very noisy! My dad is a bus driver and my mum is a nurse. Who is in your family?', fr: 'Merci pour ta lettre ! J\'habite avec ma mère, mon père et mon petit frère, Harry. Il a sept ans et il est très bruyant ! Mon père est conducteur de bus et ma mère est infirmière. Qui fait partie de ta famille ?', cond: [['lisa_moka', 'Give Moka a big hug from Biscuit!', 'Fais un gros câlin à Moka de la part de Biscuit !']],
      r: [['There is my dad Casimir, who works from home, my mum Tania, and my big brother Daryl. He is 25 and lives in his own flat.', 'Il y a mon père Casimir, qui travaille à la maison, ma mère Tania et mon grand frère Daryl. Il a 25 ans et vit dans son propre appartement.', 4, 'lisa_famille'], ['My family is my dad, my mum and my brother.', 'Ma famille, c\'est mon père, ma mère et mon frère.', 2], ['My father is cooker.', 'Mon père est cuisinier.', 0, null, '« cooker » = une cuisinière (l\'appareil) ! Un cuisinier = « a cook ».']] },
    { t: 'School in England', lv: 'A1', en: 'I am in Year 10 at Wellbrook High School. We wear a uniform: a blue jumper and a grey skirt or trousers. School starts at half past eight and finishes at three o\'clock. My favourite subject is art. What is your favourite subject?', fr: 'Je suis en Year 10 au lycée de Wellbrook (l\'équivalent de la 3e). Nous portons un uniforme : un pull bleu et une jupe ou un pantalon gris. Les cours commencent à 8 h 30 et finissent à 15 h. Ma matière préférée est l\'art. Quelle est ta matière préférée ?',
      r: [['My favourite subject is English, of course! I also like music because I play the guitar.', 'Ma matière préférée, c\'est l\'anglais bien sûr ! J\'aime aussi la musique car je joue de la guitare.', 4, 'lisa_guitare'], ['I like maths.', 'J\'aime les maths.', 2], ['My prefered matter is history.', 'Ma matière préférée est l\'histoire.', 0, null, '« matière » (scolaire) = « subject » ; et on écrit « favourite ».']] },
    { t: 'Autumn', lv: 'A1', en: 'It is autumn here. The trees in my garden are red and orange. It rains a lot, so Biscuit is always muddy! On Saturdays I go to the swimming pool with my friend Priya. What do you do at the weekend?', fr: 'C\'est l\'automne ici. Les arbres de mon jardin sont rouges et orange. Il pleut beaucoup, alors Biscuit est toujours plein de boue ! Le samedi, je vais à la piscine avec mon amie Priya. Que fais-tu le week-end ?',
      r: [['At the weekend I see my best friends, Cataleya and Elynn. On Tuesday evenings we go to dance class together.', 'Le week-end je vois mes meilleures amies, Cataleya et Elynn. Le mardi soir, nous allons au cours de danse ensemble.', 4, 'lisa_amies'], ['I sleep and I watch TV.', 'Je dors et je regarde la télé.', 2], ['I go to the cinema with my friends the Saturday.', 'Je vais au cinéma avec mes amis le samedi.', 1, null, '« le samedi » (habitude) = « on Saturdays », sans « the ».']] },
    { t: 'Bonfire Night', lv: 'A1', en: 'Next week, on the fifth of November, we celebrate Bonfire Night. There are fireworks and a big fire in the park. We eat toffee apples. It is cold but it is fun! Is there a special day in November in France?', fr: 'La semaine prochaine, le 5 novembre, nous fêtons Bonfire Night. Il y a des feux d\'artifice et un grand feu dans le parc. On mange des pommes d\'amour. Il fait froid mais c\'est amusant ! Y a-t-il un jour spécial en novembre en France ?',
      r: [['Yes, on the eleventh of November we remember the end of the First World War. There are ceremonies in every town.', 'Oui, le 11 novembre, on commémore la fin de la Première Guerre mondiale. Il y a des cérémonies dans chaque ville.', 4], ['No, nothing special.', 'Non, rien de spécial.', 1], ['Yes, the 11 November is the armistice of 1945.', 'Oui, le 11 novembre est l\'armistice de 1945.', 0, null, 'Attention : le 11 novembre commémore l\'armistice de 1918 !']] },
    { t: 'Food', lv: 'A1', en: 'Do you like French food? I love croissants! In England, we often eat beans on toast for lunch. On Sundays my dad cooks a roast dinner with potatoes and vegetables. Who cooks in your house?', fr: 'Aimes-tu la cuisine française ? J\'adore les croissants ! En Angleterre, on mange souvent des haricots à la sauce tomate sur du pain grillé le midi. Le dimanche, mon père prépare un rôti avec des pommes de terre et des légumes. Qui cuisine chez toi ?',
      r: [['My dad cooks almost every day. He makes funny pancakes in the shape of animals!', 'Mon père cuisine presque tous les jours. Il fait des crêpes rigolotes en forme d\'animaux !', 4, 'lisa_crepes'], ['My mother cooks.', 'Ma mère cuisine.', 1], ['My dad does the kitchen.', 'Mon père fait la cuisine.', 0, null, '« faire la cuisine » = « to cook » (« the kitchen » est la pièce).']] },
    { t: 'Winter plans', lv: 'A1', en: 'Christmas is coming! We put up our tree last weekend. Harry wants a robot and I want new pencils for drawing. We visit my grandma in Cambridge on Boxing Day. What do you want for Christmas?', fr: 'Noël approche ! Nous avons installé notre sapin le week-end dernier. Harry veut un robot et moi, je veux de nouveaux crayons pour dessiner. Nous rendons visite à ma grand-mère à Cambridge le lendemain de Noël. Que veux-tu pour Noël ?', cond: [['lisa_crepes', 'Maybe your dad can make Christmas pancakes!', 'Ton père peut peut-être faire des crêpes de Noël !']],
      r: [['I would like a new speaker for my bedroom because I love listening to music.', 'J\'aimerais une nouvelle enceinte pour ma chambre car j\'adore écouter de la musique.', 4], ['A phone.', 'Un téléphone.', 1], ['I want that you send me a photo of Biscuit!', 'Je veux que tu m\'envoies une photo de Biscuit !', 2, null, '« Je veux que tu… » = « I want you to send me… ».']] },
    { t: 'Happy New Year!', lv: 'A1', en: 'Happy New Year, Lyham! Thank you for the card. It snowed in Wellbrook and we made a snowman with Harry. Biscuit tried to eat its carrot nose! My birthday is in March. When is your birthday?', fr: 'Bonne année, Lyham ! Merci pour la carte. Il a neigé à Wellbrook et nous avons fait un bonhomme de neige avec Harry. Biscuit a essayé de manger son nez en carotte ! Mon anniversaire est en mars. Quand est ton anniversaire ?',
      r: [['My birthday is on the eleventh of January. I will be fifteen next week!', 'Mon anniversaire est le 11 janvier. J\'aurai quinze ans la semaine prochaine !', 4, 'lisa_anniv'], ['In January.', 'En janvier.', 1], ['My birthday is the 11 of January, I will have 15 years.', 'Mon anniversaire est le 11 janvier, j\'aurai 15 ans.', 0, null, 'On dit « on the eleventh of January » et « I will be fifteen ».']] },
    { t: 'A busy week', lv: 'A1+', en: 'This week was very busy. I had a maths test on Monday and a swimming competition on Thursday. I finished third! I was so happy. My mum took a photo of me with my medal. Did you have a good week?', fr: 'Cette semaine a été très chargée. J\'ai eu un contrôle de maths lundi et une compétition de natation jeudi. J\'ai fini troisième ! J\'étais si contente. Ma mère m\'a prise en photo avec ma médaille. As-tu passé une bonne semaine ?',
      r: [['Congratulations! Yes, I had a good week. I got a good mark in English and my dad was very proud.', 'Félicitations ! Oui, j\'ai passé une bonne semaine. J\'ai eu une bonne note en anglais et mon père était très fier.', 4], ['Yes, it was good.', 'Oui, c\'était bien.', 2], ['Yes, I have had a good week last week.', 'Oui, j\'ai eu une bonne semaine la semaine dernière.', 1, null, 'Avec « last week » (moment passé précis), on emploie le prétérit : « I had ».']] },
    { t: 'My town', lv: 'A1+', en: 'Wellbrook is small but nice. There is a market square, an old church and a river with ducks. There isn\'t a cinema, so we take the train to the next town. Is there a cinema near your house?', fr: 'Wellbrook est petite mais agréable. Il y a une place du marché, une vieille église et une rivière avec des canards. Il n\'y a pas de cinéma, alors on prend le train jusqu\'à la ville voisine. Y a-t-il un cinéma près de chez toi ?',
      r: [['Yes, there is a cinema in town. There is also a park with a pond and ducks, like in Wellbrook!', 'Oui, il y a un cinéma en ville. Il y a aussi un parc avec un étang et des canards, comme à Wellbrook !', 4], ['Yes, there is.', 'Oui, il y en a un.', 2], ['Yes, there are a cinema.', 'Oui, il y a un cinéma.', 0, null, 'Au singulier : « there is a cinema ».']] },
    { t: 'Pancake Day', lv: 'A2', en: 'Two weeks ago it was Pancake Day! In England we eat pancakes with lemon and sugar on the Tuesday before Lent. My pancake fell on the floor and Biscuit ate it in two seconds. Do you eat pancakes in France?', fr: 'Il y a deux semaines, c\'était Pancake Day ! En Angleterre, on mange des crêpes au citron et au sucre le mardi avant le Carême. Ma crêpe est tombée par terre et Biscuit l\'a mangée en deux secondes. Mangez-vous des crêpes en France ?', cond: [['lisa_crepes', 'I told my mum about your dad\'s animal pancakes. She laughed a lot!', 'J\'ai parlé des crêpes-animaux de ton père à ma mère. Elle a beaucoup ri !']],
      r: [['Yes! We eat crêpes on the second of February, for La Chandeleur. You must hold a coin while you flip them for good luck.', 'Oui ! On mange des crêpes le 2 février, pour la Chandeleur. Il faut tenir une pièce en les faisant sauter pour avoir de la chance.', 4], ['Yes, we eat crêpes.', 'Oui, on mange des crêpes.', 2], ['Yes, we eat them in February the 2.', 'Oui, on en mange le 2 février.', 1, null, 'Date : « on the second of February » ou « on February 2nd ».']] },
    { t: 'Spring holidays', lv: 'A2', en: 'Our Easter holidays start next week. We are going to visit Wales and stay in a cottage near the sea. I am going to draw the landscapes. What are you going to do during your holidays?', fr: 'Nos vacances de Pâques commencent la semaine prochaine. Nous allons visiter le pays de Galles et loger dans un petit cottage près de la mer. Je vais dessiner les paysages. Que vas-tu faire pendant tes vacances ?',
      r: [['I am going to stay at home, but I am going to go to the park with my friends and help my dad in the garden.', 'Je vais rester à la maison, mais je vais aller au parc avec mes amies et aider mon père au jardin.', 4], ['I am going to relax.', 'Je vais me détendre.', 2], ['I will going to the beach.', 'Je vais aller à la plage.', 0, null, 'Soit « I will go », soit « I am going to go » — pas les deux !']] },
    { t: 'In Wales', lv: 'A2', en: 'Wales was beautiful! We walked on the cliffs and saw seals on the rocks. It rained every day, but we didn\'t care. I drew twelve pictures. I am sending you one of them. What did you do?', fr: 'Le pays de Galles était magnifique ! Nous avons marché sur les falaises et vu des phoques sur les rochers. Il a plu tous les jours, mais ça nous était égal. J\'ai fait douze dessins. Je t\'en envoie un. Et toi, qu\'as-tu fait ?',
      r: [['Thank you for the drawing, it is on my bedroom wall now! I went to the park and played football with Moka. He chased the ball everywhere!', 'Merci pour le dessin, il est accroché au mur de ma chambre ! Je suis allée au parc et j\'ai joué au ballon avec Moka. Il a couru après le ballon partout !', 5, 'lisa_dessin'], ['I stayed at home.', 'Je suis restée à la maison.', 2], ['I have went to the cinema.', 'Je suis allée au cinéma.', 0, null, 'Prétérit de « go » : « I went » (participe : gone).']] },
    { t: 'Exams', lv: 'A2', en: 'I am a bit stressed because we have mock exams soon. I revise every evening with flashcards. My teacher says I need to sleep more! How do you revise for tests?', fr: 'Je suis un peu stressée car nous avons bientôt des examens blancs. Je révise chaque soir avec des fiches. Mon professeur dit que je dois dormir davantage ! Comment révises-tu pour tes contrôles ?',
      r: [['I make mind maps with colours and I explain the lessons to my cat. He is a very good listener!', 'Je fais des cartes mentales en couleurs et j\'explique les leçons à mon chat. Il écoute très bien !', 4], ['I read my lessons.', 'Je relis mes leçons.', 2], ['I revise since two hours every day.', 'Je révise depuis deux heures chaque jour.', 0, null, 'Une durée = « for two hours ». « Since » + point de départ.']] },
    { t: 'A funny story', lv: 'A2', en: 'Something funny happened yesterday. Harry hid my sketchbook in the washing machine! Luckily, my mum found it before she started it. I was angry, but now I think it is funny. Do you argue with your brother?', fr: 'Il s\'est passé quelque chose de drôle hier. Harry a caché mon carnet de croquis dans la machine à laver ! Heureusement, ma mère l\'a trouvé avant de la lancer. J\'étais en colère, mais maintenant je trouve ça drôle. Te disputes-tu avec ton frère ?',
      r: [['Not really, because Daryl doesn\'t live with us. But when he visits, we always argue about video games!', 'Pas vraiment, car Daryl ne vit pas avec nous. Mais quand il vient, on se dispute toujours à propos des jeux vidéo !', 4, 'lisa_daryl'], ['Sometimes.', 'Parfois.', 1], ['Yes, we argue us a lot.', 'Oui, on se dispute beaucoup.', 1, null, '« argue » n\'est pas pronominal : « we argue a lot ».']] },
    { t: 'Summer is coming', lv: 'A2', en: 'The days are longer now and it is warmer. After school, I sit in the garden and read. Biscuit sleeps in the sun all afternoon. Mum says he is the laziest dog in England! Is your cat lazy too?', fr: 'Les jours sont plus longs et il fait plus chaud. Après l\'école, je m\'assieds dans le jardin et je lis. Biscuit dort au soleil tout l\'après-midi. Maman dit que c\'est le chien le plus paresseux d\'Angleterre ! Ton chat est-il paresseux aussi ?',
      r: [['Moka is lazier than Biscuit, I think! He sleeps for sixteen hours a day, except when he sees his red ball.', 'Je pense que Moka est encore plus paresseux que Biscuit ! Il dort seize heures par jour, sauf quand il voit sa balle rouge.', 4], ['Yes, very lazy.', 'Oui, très paresseux.', 2], ['He is more lazy than your dog.', 'Il est plus paresseux que ton chien.', 1, null, 'Adjectif court en -y : « lazier than ».']] },
    { t: 'End of the school year', lv: 'A2', en: 'School finishes in July here. We had a sports day last Friday and my team won the relay race. Next year I will start studying for my GCSEs. They are important exams. Do you have exams at the end of this year?', fr: 'L\'école finit en juillet ici. Nous avons eu une journée sportive vendredi dernier et mon équipe a gagné le relais. L\'année prochaine, je commencerai à préparer mes GCSE. Ce sont des examens importants. As-tu des examens à la fin de cette année ?',
      r: [['Yes, I will take the brevet in June. There is French, maths, history-geography and science.', 'Oui, je passerai le brevet en juin. Il y a du français, des maths, de l\'histoire-géo et des sciences.', 4, 'lisa_brevet'], ['Yes, the brevet.', 'Oui, le brevet.', 2], ['Yes, I pass the brevet in June.', 'Oui, je passe le brevet en juin.', 0, null, 'Faux-ami : « pass an exam » = réussir. Passer un examen = « take an exam ».']] },
    { t: 'Music', lv: 'A2', en: 'You told me you play the guitar. That is so cool! I can\'t play an instrument, but I sing in the school choir. We are preparing a concert for the end of the term. What kind of music do you like?', fr: 'Tu m\'as dit que tu joues de la guitare. C\'est trop bien ! Je ne sais jouer d\'aucun instrument, mais je chante dans la chorale de l\'école. Nous préparons un concert pour la fin du trimestre. Quel genre de musique aimes-tu ?', cond: [['lisa_guitare', 'Can you play a song for me one day?', 'Pourras-tu me jouer une chanson un jour ?']],
      r: [['I like pop and chill music. I listen to music in my bedroom when I do my homework. It helps me concentrate.', 'J\'aime la pop et la musique chill. J\'en écoute dans ma chambre quand je fais mes devoirs. Ça m\'aide à me concentrer.', 4], ['I like pop.', 'J\'aime la pop.', 2], ['I like very much the rock.', 'J\'aime beaucoup le rock.', 1, null, 'Ordre des mots : « I really like rock » (pas d\'article pour un genre en général).']] },
    { t: 'Friends', lv: 'A2+', en: 'Priya and I have been friends since primary school. She is funny and kind, but she is always late! Last week she arrived at the cinema when the film had already started. How did you meet your best friends?', fr: 'Priya et moi sommes amies depuis l\'école primaire. Elle est drôle et gentille, mais elle est toujours en retard ! La semaine dernière, elle est arrivée au cinéma quand le film avait déjà commencé. Comment as-tu rencontré tes meilleures amies ?', cond: [['lisa_amies', 'Say hello to Cataleya and Elynn from me!', 'Dis bonjour à Cataleya et Elynn de ma part !']],
      r: [['I have known Elynn since I was four. We used to build huts together. I met Cataleya at school: she is in my class.', 'Je connais Elynn depuis mes quatre ans. On construisait des cabanes ensemble. J\'ai rencontré Cataleya à l\'école : elle est dans ma classe.', 5, 'lisa_cabane'], ['At school.', 'À l\'école.', 1], ['I know Elynn since I am four.', 'Je connais Elynn depuis que j\'ai quatre ans.', 1, null, '« I have known Elynn since I was four » : present perfect + since + prétérit.']] },
    { t: 'A rainy day', lv: 'A2+', en: 'It has been raining for three days! The river is very high and some roads are closed. We stayed inside and played board games. Harry cheated, of course. What do you do when it rains?', fr: 'Il pleut depuis trois jours ! La rivière est très haute et certaines routes sont fermées. Nous sommes restés à l\'intérieur et avons joué à des jeux de société. Harry a triché, évidemment. Que fais-tu quand il pleut ?',
      r: [['When it rains, I watch documentaries about the ocean or I play the piano in the living room.', 'Quand il pleut, je regarde des documentaires sur l\'océan ou je joue du piano dans le salon.', 4], ['I stay at home.', 'Je reste à la maison.', 2], ['When it will rain, I read.', 'Quand il pleuvra, je lis.', 0, null, 'Après « when », pas de futur : « when it rains ».']] },
    { t: 'Volunteering', lv: 'B1', en: 'This term I have started volunteering at an animal shelter on Saturday mornings. I walk the dogs and clean the cages. It is hard work, but I feel useful. Have you ever done any volunteering?', fr: 'Ce trimestre, j\'ai commencé à faire du bénévolat dans un refuge pour animaux le samedi matin. Je promène les chiens et je nettoie les cages. C\'est un travail difficile, mais je me sens utile. As-tu déjà fait du bénévolat ?',
      r: [['Not yet, but I would love to. Maybe I could help at the library or with younger pupils.', 'Pas encore, mais j\'adorerais. Je pourrais peut-être aider à la bibliothèque ou avec des élèves plus jeunes.', 4], ['No, never.', 'Non, jamais.', 1], ['No, I never did.', 'Non, je ne l\'ai jamais fait.', 1, null, 'Expérience sans date : « No, I have never done any. »']] },
    { t: 'Technology', lv: 'B1', en: 'My parents think I spend too much time on my phone. They have made a rule: no screens after nine o\'clock. At first I was annoyed, but actually I sleep better now. Do your parents have rules about screens?', fr: 'Mes parents pensent que je passe trop de temps sur mon téléphone. Ils ont instauré une règle : pas d\'écran après 21 h. Au début j\'étais agacée, mais en fait je dors mieux maintenant. Tes parents ont-ils des règles sur les écrans ?',
      r: [['Yes, my dad and I made a deal: no phone at dinner. It was difficult at first, but we talk much more now.', 'Oui, mon père et moi avons passé un accord : pas de téléphone pendant le dîner. C\'était difficile au début, mais on discute beaucoup plus maintenant.', 5, 'lisa_ecrans'], ['Yes, a few.', 'Oui, quelques-unes.', 2], ['Yes, I must not to use my phone at dinner.', 'Oui, je ne dois pas utiliser mon téléphone au dîner.', 1, null, 'Après un modal, base verbale sans « to » : « I must not use ».']] },
    { t: 'My dream job', lv: 'B1', en: 'Our teacher asked us what we want to do in the future. I would like to become an illustrator for children\'s books. If I could, I would live in a little house by the sea and draw all day. What would you like to do later?', fr: 'Notre professeur nous a demandé ce que nous voulons faire plus tard. J\'aimerais devenir illustratrice de livres pour enfants. Si je pouvais, je vivrais dans une petite maison au bord de la mer et je dessinerais toute la journée. Que voudrais-tu faire plus tard ?',
      r: [['I am not sure yet. I would like a job where I can travel and speak English. Maybe a journalist or a translator!', 'Je ne suis pas encore sûre. J\'aimerais un métier où je peux voyager et parler anglais. Peut-être journaliste ou traductrice !', 4, 'lisa_metier'], ['I don\'t know.', 'Je ne sais pas.', 1], ['If I could, I will be a dancer.', 'Si je pouvais, je serais danseuse.', 1, null, 'Concordance : « If I could, I would be… ».']] },
    { t: 'A trip to London', lv: 'B1', en: 'Last Saturday we went to London to see the Natural History Museum. The dinosaur skeleton was enormous! Then we walked along the Thames and ate fish and chips. Have you ever been to London?', fr: 'Samedi dernier, nous sommes allés à Londres voir le Muséum d\'histoire naturelle. Le squelette de dinosaure était énorme ! Ensuite, nous avons marché le long de la Tamise et mangé du fish and chips. Es-tu déjà allée à Londres ?',
      r: [['No, I have never been to London, but I would love to visit it with you one day!', 'Non, je ne suis jamais allée à Londres, mais j\'adorerais la visiter avec toi un jour !', 5, 'lisa_promesse_londres'], ['No.', 'Non.', 1], ['No, I never went in London.', 'Non, je ne suis jamais allée à Londres.', 1, null, '« I have never been to London » (present perfect, « to »).']] },
    { t: 'Feeling down', lv: 'B1', en: 'To be honest, I haven\'t been very happy this week. Priya and I had an argument about something silly and now she isn\'t talking to me. I don\'t know what to do. What would you do in my place?', fr: 'Pour être honnête, je n\'ai pas été très heureuse cette semaine. Priya et moi nous sommes disputées pour une bêtise et maintenant elle ne me parle plus. Je ne sais pas quoi faire. Que ferais-tu à ma place ?',
      r: [['If I were you, I would write her a short message to say sorry. A true friend doesn\'t stay angry for long.', 'Si j\'étais toi, je lui écrirais un petit message pour m\'excuser. Une vraie amie ne reste pas fâchée longtemps.', 5, 'lisa_conseil'], ['Don\'t worry.', 'Ne t\'inquiète pas.', 2], ['If I am you, I will call her.', 'Si j\'étais toi, je l\'appellerais.', 1, null, 'Conseil : « If I were you, I would… ».']] },
    { t: 'Good news', lv: 'B1', en: 'Thank you for your advice! I sent Priya a message and we made up the next day. We laughed about our argument. You are a really good friend, even from far away. How are things with Cataleya and Elynn?', fr: 'Merci pour ton conseil ! J\'ai envoyé un message à Priya et nous nous sommes réconciliées le lendemain. Nous avons ri de notre dispute. Tu es une vraie amie, même de loin. Comment ça va avec Cataleya et Elynn ?', cond: [['lisa_conseil', 'I followed your advice exactly!', 'J\'ai suivi ton conseil à la lettre !']],
      r: [['Everything is fine! We are preparing a dance show for the end of the year. Mme Lopez is very strict, but we love her.', 'Tout va bien ! Nous préparons un spectacle de danse pour la fin de l\'année. Mme Lopez est très stricte, mais on l\'adore.', 4], ['Fine, thanks.', 'Bien, merci.', 2], ['It goes well.', 'Ça va bien.', 0, null, 'Calque de « ça va bien » : dis plutôt « Things are going well. »']] },
    { t: 'The environment', lv: 'B1', en: 'At school we have started an eco-club. We have planted trees and we are trying to reduce plastic in the canteen. Some people think small actions are useless, but I disagree. What does your school do for the environment?', fr: 'À l\'école, nous avons lancé un éco-club. Nous avons planté des arbres et nous essayons de réduire le plastique à la cantine. Certains pensent que les petites actions sont inutiles, mais je ne suis pas d\'accord. Que fait ton école pour l\'environnement ?',
      r: [['We sort our waste and there is a vegetable garden. At home, I grow flowers and tomatoes in our garden.', 'Nous trions nos déchets et il y a un potager. À la maison, je fais pousser des fleurs et des tomates dans notre jardin.', 4], ['Not much.', 'Pas grand-chose.', 1], ['We make attention to the planet.', 'Nous faisons attention à la planète.', 0, null, '« faire attention » = « to be careful / to take care of ».']] },
    { t: 'Books', lv: 'B1', en: 'I have just finished a brilliant novel about a girl who travels back in time. I read it in two days! I couldn\'t stop. Have you read anything good recently?', fr: 'Je viens de finir un roman génial sur une fille qui voyage dans le temps. Je l\'ai lu en deux jours ! Je ne pouvais pas m\'arrêter. As-tu lu quelque chose de bien récemment ?',
      r: [['Yes, I have just read a French novel from the school library. It was so exciting that I read it in one night!', 'Oui, je viens de lire un roman français emprunté au CDI. C\'était si passionnant que je l\'ai lu en une nuit !', 4], ['No, I don\'t like reading.', 'Non, je n\'aime pas lire.', 1], ['Yes, I have read a book last week.', 'Oui, j\'ai lu un livre la semaine dernière.', 1, null, 'Avec « last week » : prétérit « I read ».']] },
    { t: 'A big decision', lv: 'B1', en: 'My parents are thinking about moving to Scotland because my dad has been offered a new job. I don\'t want to leave my friends, but Scotland is beautiful. It is complicated! Have you ever moved house?', fr: 'Mes parents envisagent de déménager en Écosse car on a proposé un nouveau travail à mon père. Je ne veux pas quitter mes amis, mais l\'Écosse est magnifique. C\'est compliqué ! As-tu déjà déménagé ?',
      r: [['No, never. I understand how you feel. Whatever happens, we will keep writing to each other, I promise.', 'Non, jamais. Je comprends ce que tu ressens. Quoi qu\'il arrive, nous continuerons à nous écrire, je te le promets.', 6, 'lisa_promesse'], ['No.', 'Non.', 1], ['No, but Scotland is more far.', 'Non, mais l\'Écosse est plus loin.', 1, null, 'Comparatif irrégulier : « farther / further ».']] },
    { t: 'Staying!', lv: 'B1', en: 'Great news: we are staying in Wellbrook! My dad decided to refuse the job because it was too far from my grandma. I was so relieved that I cried. Thank you for your kind words last time. They meant a lot to me.', fr: 'Super nouvelle : nous restons à Wellbrook ! Mon père a décidé de refuser le poste car c\'était trop loin de ma grand-mère. J\'étais tellement soulagée que j\'ai pleuré. Merci pour tes mots gentils la dernière fois. Ils ont beaucoup compté pour moi.', cond: [['lisa_promesse', 'And I know you would have kept your promise anyway.', 'Et je sais que tu aurais tenu ta promesse de toute façon.']],
      r: [['I am so happy for you! Your dad made a wise decision. Family is the most important thing.', 'Je suis tellement contente pour toi ! Ton père a pris une sage décision. La famille, c\'est le plus important.', 4], ['Good news!', 'Bonne nouvelle !', 2], ['I am happy that you stay.', 'Je suis contente que tu restes.', 2, null, 'Correct, mais plus naturel : « I\'m so glad you\'re staying! »']] },
    { t: 'Halloween', lv: 'B1', en: 'For Halloween, Harry dressed up as a zombie and I was a witch. We went trick-or-treating in our street and came back with a huge bag of sweets. My mum hid half of it! Is Halloween popular in France?', fr: 'Pour Halloween, Harry s\'est déguisé en zombie et moi en sorcière. Nous sommes allés réclamer des bonbons dans notre rue et sommes revenus avec un énorme sac de friandises. Ma mère en a caché la moitié ! Halloween est-il populaire en France ?',
      r: [['It is less popular than in England, but some children dress up. We celebrate All Saints\' Day on the first of November.', 'C\'est moins populaire qu\'en Angleterre, mais certains enfants se déguisent. Nous fêtons la Toussaint le 1er novembre.', 4], ['Not really.', 'Pas vraiment.', 2], ['It is less popular that in England.', 'C\'est moins populaire qu\'en Angleterre.', 1, null, 'Comparatif : « less popular than ».']] },
    { t: 'Opinions', lv: 'B1+', en: 'In our English class we debated whether school uniforms should be compulsory. I argued against them because I think clothes help us express our personality. However, my friend said uniforms reduce inequality. What is your opinion?', fr: 'En cours d\'anglais, nous avons débattu pour savoir si l\'uniforme devrait être obligatoire. J\'ai argumenté contre, car je pense que les vêtements nous aident à exprimer notre personnalité. Cependant, mon amie a dit que l\'uniforme réduit les inégalités. Quel est ton avis ?',
      r: [['I see both sides. On the one hand, uniforms reduce pressure about brands; on the other hand, they can feel like a limit to our freedom.', 'Je vois les deux côtés. D\'un côté, l\'uniforme réduit la pression des marques ; de l\'autre, il peut sembler limiter notre liberté.', 5, 'lisa_debat'], ['I agree with you.', 'Je suis d\'accord avec toi.', 2], ['I am agree with your friend.', 'Je suis d\'accord avec ton amie.', 0, null, '« I agree » (agree est un verbe, pas d\'auxiliaire « am »).']] },
    { t: 'Snow day', lv: 'B1+', en: 'School was closed yesterday because of the snow! It was the first snow day I had ever had. We built an igloo in the garden, although it collapsed after an hour. Biscuit was totally confused by the snow. Does it often snow where you live?', fr: 'L\'école était fermée hier à cause de la neige ! C\'était la première fois de ma vie que l\'école fermait pour la neige. Nous avons construit un igloo dans le jardin, même s\'il s\'est effondré au bout d\'une heure. Biscuit était complètement perdu dans la neige. Neige-t-il souvent chez toi ?',
      r: [['It rarely snows near Paris. When it does, everything stops, and Moka watches the snowflakes from the window.', 'Il neige rarement près de Paris. Quand ça arrive, tout s\'arrête, et Moka regarde les flocons depuis la fenêtre.', 4], ['Not often.', 'Pas souvent.', 2], ['It snows rarely in my city.', 'Il neige rarement dans ma ville.', 2, null, 'Place de l\'adverbe : « It rarely snows ».']] },
    { t: 'Grandma', lv: 'B1+', en: 'My grandma is in hospital. The doctors say she will be fine, but I am worried. She is the one who taught me to draw when I was little. I am making her a card with all the birds she loves. Are you close to your grandparents?', fr: 'Ma grand-mère est à l\'hôpital. Les médecins disent qu\'elle ira bien, mais je suis inquiète. C\'est elle qui m\'a appris à dessiner quand j\'étais petite. Je lui fabrique une carte avec tous les oiseaux qu\'elle aime. Es-tu proche de tes grands-parents ?',
      r: [['I hope she gets better soon. Your card will make her smile. I am thinking of you and your family.', 'J\'espère qu\'elle va vite se rétablir. Ta carte la fera sourire. Je pense à toi et à ta famille.', 6, 'lisa_soutien'], ['Get well soon to her.', 'Bon rétablissement à elle.', 2], ['I hope she will be better soon. Courage!', 'J\'espère qu\'elle ira mieux bientôt. Courage !', 2, null, '« Courage ! » se dit plutôt « Hang in there! » ou « Stay strong! ».']] },
    { t: 'Thank you', lv: 'B1+', en: 'Grandma came home last week and she put your card next to mine on her shelf! She says you write beautiful English. She wants to know if you would like to visit us one summer. My parents agree. Would you like to come?', fr: 'Grand-mère est rentrée la semaine dernière et elle a posé ta carte à côté de la mienne sur son étagère ! Elle dit que tu écris un très bel anglais. Elle voudrait savoir si tu aimerais nous rendre visite un été. Mes parents sont d\'accord. Aimerais-tu venir ?', cond: [['lisa_soutien', 'Your message really cheered her up.', 'Ton message lui a vraiment remonté le moral.']],
      r: [['I would love to! I will ask my parents tonight. It would be a dream to meet you and Biscuit in real life.', 'J\'adorerais ! Je demanderai à mes parents ce soir. Ce serait un rêve de vous rencontrer, toi et Biscuit, en vrai.', 6, 'lisa_invitation'], ['Maybe.', 'Peut-être.', 1], ['Yes, I want very much.', 'Oui, je veux beaucoup.', 1, null, '« I\'d love to! » ou « I\'d really like to! »']] },
    { t: 'Passions', lv: 'B1+', en: 'I have been taking pottery lessons for a month. My first bowl looked like a potato, but my teacher says I am improving. I think it is important to try new things, even if you are bad at them at first. Is there something new you would like to try?', fr: 'Je prends des cours de poterie depuis un mois. Mon premier bol ressemblait à une pomme de terre, mais mon professeur dit que je progresse. Je pense qu\'il est important d\'essayer de nouvelles choses, même si on est mauvais au début. Y a-t-il quelque chose de nouveau que tu aimerais essayer ?',
      r: [['I would like to try ice skating properly. Every time I go to the rink, I spend more time on the ice than on my skates!', 'J\'aimerais apprendre à patiner correctement. Chaque fois que je vais à la patinoire, je passe plus de temps sur la glace que sur mes patins !', 4], ['Yes, skating.', 'Oui, le patin.', 2], ['I would like try skating.', 'J\'aimerais essayer le patin.', 1, null, '« I would like to try skating » (to + base verbale).']] },
    { t: 'News from France', lv: 'B1+', en: 'I watched a documentary about Paris last night. It looked amazing, especially the Eiffel Tower lit up at night. But I read that it is very busy with tourists. If I visited, what would you recommend I see?', fr: 'J\'ai regardé un documentaire sur Paris hier soir. C\'était magnifique, surtout la tour Eiffel illuminée la nuit. Mais j\'ai lu qu\'il y a énormément de touristes. Si je venais, que me recommanderais-tu de voir ?',
      r: [['I would recommend a walk along the Seine at sunset, a picnic in a park and, of course, a crêpe made by my dad!', 'Je te recommanderais une balade le long de la Seine au coucher du soleil, un pique-nique dans un parc et, bien sûr, une crêpe préparée par mon père !', 5, 'lisa_paris'], ['The Eiffel Tower.', 'La tour Eiffel.', 1], ['I recommend you to visit the Louvre.', 'Je te recommande de visiter le Louvre.', 1, null, 'On dit « I recommend visiting » ou « I recommend that you visit ».']] },
    { t: 'Reported news', lv: 'B2', en: 'My form tutor told us that the school would organise an exchange with a French school next year! She said that only twelve students could go, so I have already written my application. Imagine if it were your school…', fr: 'Ma professeure principale nous a dit que l\'école organiserait un échange avec un établissement français l\'année prochaine ! Elle a dit que seulement douze élèves pourraient y aller, alors j\'ai déjà écrit ma candidature. Imagine si c\'était ton école…',
      r: [['That would be incredible! I will ask my English teacher whether our school could take part. Fingers crossed!', 'Ce serait incroyable ! Je vais demander à ma professeure d\'anglais si notre école pourrait participer. Croisons les doigts !', 5], ['Good luck!', 'Bonne chance !', 2], ['My teacher said me that it is possible.', 'Ma prof m\'a dit que c\'est possible.', 1, null, '« said that… » ou « told me that… » — jamais « said me ».']] },
    { t: 'Was it written?', lv: 'B2', en: 'Did you know that the first postcard was sent in 1840 in London? It was written by a writer who posted it to himself as a joke! Our letters are part of a long tradition. Sometimes I think letters are more personal than messages. Do you agree?', fr: 'Savais-tu que la première carte postale a été envoyée en 1840 à Londres ? Elle a été écrite par un écrivain qui se l\'est envoyée pour plaisanter ! Nos lettres font partie d\'une longue tradition. Je pense parfois que les lettres sont plus personnelles que les messages. Es-tu d\'accord ?',
      r: [['I totally agree. A letter is written slowly, so every word is chosen. I keep all of yours in a box.', 'Je suis tout à fait d\'accord. Une lettre s\'écrit lentement, chaque mot est choisi. Je garde toutes les tiennes dans une boîte.', 6, 'lisa_boite'], ['Yes.', 'Oui.', 1], ['Yes, letters are more personals.', 'Oui, les lettres sont plus personnelles.', 1, null, 'Les adjectifs anglais sont invariables : « more personal ».']] },
    { t: 'Big questions', lv: 'B2', en: 'Our philosophy club discussed a strange question: would you rather be famous or happy? Most people said happy, but I wonder if fame would bring some happiness too. I am curious about what you think.', fr: 'Notre club de philosophie a débattu d\'une question étrange : préférerais-tu être célèbre ou heureuse ? La plupart ont répondu heureux, mais je me demande si la célébrité n\'apporterait pas aussi un peu de bonheur. Je suis curieuse de savoir ce que tu en penses.',
      r: [['I would rather be happy. Fame depends on what others think of you, whereas happiness depends more on yourself and the people you love.', 'Je préférerais être heureuse. La célébrité dépend de ce que les autres pensent de toi, alors que le bonheur dépend davantage de toi et des gens que tu aimes.', 5, 'lisa_philo'], ['Happy.', 'Heureuse.', 1], ['I prefer to be happy than famous.', 'Je préfère être heureuse que célèbre.', 1, null, '« I would rather be happy than famous. »']] },
    { t: 'Exam season', lv: 'B2', en: 'My exams are over and I think they went well, although the history paper was harder than expected. How about your brevet? I really hope it went brilliantly. Whatever the result, I am proud of you for working so hard.', fr: 'Mes examens sont finis et je pense qu\'ils se sont bien passés, même si l\'épreuve d\'histoire était plus difficile que prévu. Et ton brevet ? J\'espère vraiment que ça s\'est très bien passé. Quel que soit le résultat, je suis fière de toi d\'avoir autant travaillé.', cond: [['lisa_brevet', 'I remembered the date you told me!', 'Je me suis souvenue de la date que tu m\'avais donnée !']],
      r: [['Thank you! I felt ready thanks to a week of revision with my parents and friends. I will tell you my results in July!', 'Merci ! Je me sentais prête grâce à une semaine de révisions avec mes parents et mes amies. Je te donnerai mes résultats en juillet !', 5], ['It was okay.', 'Ça s\'est bien passé.', 2], ['It passed well.', 'Ça s\'est bien passé.', 0, null, 'Calque ! Dis : « It went well. »']] },
    { t: 'One year of letters', lv: 'B2', en: 'Can you believe we have been writing to each other for almost a year? When I read my first letter again, I laughed: my sentences were so simple! Your English has improved enormously too. Shall we keep writing next year, even when we are busier?', fr: 'Tu te rends compte que nous nous écrivons depuis presque un an ? Quand j\'ai relu ma première lettre, j\'ai ri : mes phrases étaient si simples ! Ton anglais s\'est énormément amélioré aussi. Continuerons-nous à nous écrire l\'année prochaine, même si nous sommes plus occupées ?',
      r: [['Of course! Our letters have become part of my life. I would never stop, however busy I am.', 'Bien sûr ! Nos lettres font maintenant partie de ma vie. Je n\'arrêterais jamais, aussi occupée que je sois.', 6, 'lisa_pour_toujours'], ['Yes, okay.', 'Oui, d\'accord.', 2], ['Yes, we continue.', 'Oui, on continue.', 1, null, 'Pour une promesse : « Yes, we will keep writing! »']] }
  ];

  /* Lettres supplémentaires et ordre chronologique (une lettre par semaine, de la rentrée de 3e à juillet) */
  L.push({ t: 'Half-term', lv: 'A1', en: 'It is half-term here: we have a week off school! I am staying at home with Harry. We went to the farm yesterday and fed the goats. One goat ate my glove! Do you have holidays in October too?', fr: 'Ce sont les vacances de mi-trimestre ici : une semaine sans école ! Je reste à la maison avec Harry. Hier, nous sommes allés à la ferme et avons nourri les chèvres. Une chèvre a mangé mon gant ! As-tu des vacances en octobre aussi ?',
    r: [['Yes! We have two weeks off for All Saints\' Day. I am going to sleep, read and play with Moka.', 'Oui ! Nous avons deux semaines de vacances pour la Toussaint. Je vais dormir, lire et jouer avec Moka.', 4], ['Yes, two weeks.', 'Oui, deux semaines.', 2], ['Yes, we have holidays during two weeks.', 'Oui, nous avons des vacances pendant deux semaines.', 1, null, 'Une durée : « for two weeks ».']] });
  L.push({ t: 'Christmas holidays', lv: 'A2', en: 'The Christmas holidays have started! Our house smells of gingerbread because my mum baked all afternoon. Harry wrote a very long letter to Father Christmas. How do you celebrate Christmas in your family?', fr: 'Les vacances de Noël ont commencé ! Notre maison sent le pain d\'épices car ma mère a fait des gâteaux tout l\'après-midi. Harry a écrit une très longue lettre au Père Noël. Comment fêtes-vous Noël dans ta famille ?',
    r: [['On Christmas Eve, Daryl comes home, my dad cooks a big dinner and we open presents at midnight.', 'Le soir du réveillon, Daryl rentre à la maison, mon père prépare un grand dîner et nous ouvrons les cadeaux à minuit.', 4], ['With my family.', 'En famille.', 2], ['We eat together the 24 December.', 'Nous mangeons ensemble le 24 décembre.', 1, null, '« on the 24th of December » ; et l\'adverbe se place après : « we eat together on… ».']] });
  L.push({ t: 'Boxing Day', lv: 'A2', en: 'I hope you had a lovely Christmas! We spent Boxing Day at my grandma\'s house in Cambridge. She gave me a beautiful box of watercolours. We played charades and my dad pretended to be a penguin. What was your favourite present?', fr: 'J\'espère que tu as passé un joyeux Noël ! Nous avons passé le lendemain de Noël chez ma grand-mère à Cambridge. Elle m\'a offert une magnifique boîte d\'aquarelles. Nous avons joué aux mimes et mon père a imité un pingouin. Quel était ton cadeau préféré ?',
    r: [['My favourite present was a new speaker for my bedroom. Now my music is louder… and my parents are less happy!', 'Mon cadeau préféré était une nouvelle enceinte pour ma chambre. Maintenant ma musique est plus forte… et mes parents moins contents !', 4], ['A speaker.', 'Une enceinte.', 2], ['My prefered gift was a speaker.', 'Mon cadeau préféré était une enceinte.', 1, null, 'Orthographe : « favourite » (anglais britannique).']] });
  L.push({ t: 'Good luck!', lv: 'B2', en: 'By the time you read this letter, you will probably have finished your brevet. I have been thinking about you all week. Whatever happens, remember how much progress you have made this year. Biscuit sends you a lucky paw!', fr: 'Quand tu liras cette lettre, tu auras probablement terminé ton brevet. J\'ai pensé à toi toute la semaine. Quoi qu\'il arrive, souviens-toi de tous les progrès que tu as faits cette année. Biscuit t\'envoie une patte porte-bonheur !',
    r: [['Thank you so much! Your letter arrived at the perfect moment. I felt calm and confident during the exams.', 'Merci beaucoup ! Ta lettre est arrivée au moment parfait. Je me suis sentie calme et confiante pendant les épreuves.', 5], ['Thanks!', 'Merci !', 2], ['Thank you, I was very stressed but it is past.', 'Merci, j\'étais très stressée mais c\'est passé.', 1, null, '« it\'s over » = c\'est terminé ; « past » est un nom ou une préposition.']] });
  var ORDRE = ['Hello from Wellbrook!', 'My family', 'School in England', 'Autumn', 'Food', 'My town', 'A busy week', 'Half-term', 'Bonfire Night', 'Halloween', 'A funny story', 'A rainy day', 'Music', 'Friends', 'Winter plans', 'Christmas holidays', 'Boxing Day', 'Happy New Year!', 'Snow day', 'Volunteering', 'Technology', 'My dream job', 'A trip to London', 'Opinions', 'Exams', 'Feeling down', 'Good news', 'Pancake Day', 'The environment', 'Spring holidays', 'Books', 'Passions', 'In Wales', 'A big decision', 'Staying!', 'Summer is coming', 'Grandma', 'Thank you', 'News from France', 'End of the school year', 'Reported news', 'Was it written?', 'Good luck!', 'Exam season', 'Big questions', 'One year of letters'];
  var parTitre = {}; L.forEach(function (x) { parTitre[x.t] = x; });
  L = ORDRE.map(function (t) { if (!parTitre[t]) throw new Error('Lettre introuvable : ' + t); return parTitre[t]; });
  function niv(i) { return i < 10 ? 'A1' : i < 20 ? 'A2' : i < 33 ? 'B1' : 'B2'; }
  LL.LETTRES = L.map(function (x, i) { return { id: 'lisa_' + (i + 1), n: i + 1, titre: x.t, niveau: niv(i), en: x.en, fr: x.fr, cond: x.cond || [], replies: x.r.map(function (r) { return { en: r[0], fr: r[1], rel: r[2], flag: r[3] || null, note: r[4] || null }; }) }; });

  /* ---------- Après la 40e lettre : lettres hebdomadaires de niveau lycée (B2), composées à partir de banques distinctes ---------- */
  var MOIS_EN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  var OPEN = [['The garden is covered in frost this morning and Biscuit refuses to go out.', 'Le jardin est couvert de givre ce matin et Biscuit refuse de sortir.'], ['February in Wellbrook means grey skies, but the first snowdrops have appeared.', 'Février à Wellbrook, c\'est le ciel gris, mais les premiers perce-neige sont apparus.'], ['Spring has finally arrived and the market square is full of daffodils.', 'Le printemps est enfin là et la place du marché est pleine de jonquilles.'], ['April showers have turned our garden into a jungle.', 'Les giboulées d\'avril ont transformé notre jardin en jungle.'], ['The evenings are long and warm, and everyone is outside.', 'Les soirées sont longues et douces, tout le monde est dehors.'], ['June is exam month here, so the whole town seems to be revising.', 'Juin est le mois des examens ici, toute la ville semble réviser.'], ['Summer holidays at last! I am writing this letter in the garden.', 'Enfin les vacances d\'été ! Je t\'écris depuis le jardin.'], ['August is hot this year and the river is very low.', 'Il fait chaud en août cette année et la rivière est très basse.'], ['A new school year has begun and my timetable is terrifying.', 'Une nouvelle année scolaire a commencé et mon emploi du temps est terrifiant.'], ['The leaves are turning gold along the river.', 'Les feuilles deviennent dorées le long de la rivière.'], ['November is dark and rainy, perfect weather for hot chocolate.', 'Novembre est sombre et pluvieux, le temps parfait pour un chocolat chaud.'], ['The Christmas lights are up in Wellbrook and Harry is overexcited.', 'Les illuminations de Noël sont installées à Wellbrook et Harry est surexcité.']];
  var NEWS = [ // par niveau du lycée (Lisa : Year 11 GCSE, puis Year 12-13 A-levels)
    [['I have chosen my GCSE art project: portraits of people in my town.', 'J\'ai choisi mon projet d\'art pour le GCSE : des portraits des habitants de ma ville.'], ['Our maths teacher gives us a mock exam every Friday, which is exhausting.', 'Notre prof de maths nous donne un examen blanc chaque vendredi, c\'est épuisant.'], ['I started a part-time job at the bakery on Saturdays.', 'J\'ai commencé un petit boulot à la boulangerie le samedi.'], ['Priya and I joined the school newspaper and I draw the cartoons.', 'Priya et moi avons rejoint le journal du lycée et je dessine les caricatures.'], ['Harry has started learning the violin and our ears are suffering.', 'Harry a commencé le violon et nos oreilles souffrent.'], ['We visited a sixth-form college to prepare for next year.', 'Nous avons visité un lycée pour préparer l\'année prochaine.'], ['I got my GCSE results and I passed everything, even physics!', 'J\'ai eu mes résultats du GCSE et j\'ai tout réussi, même la physique !'], ['Biscuit learnt to open the fridge, which is a disaster.', 'Biscuit a appris à ouvrir le frigo, c\'est une catastrophe.']],
    [['I have chosen my A-levels: art, English literature and French.', 'J\'ai choisi mes A-levels : art, littérature anglaise et français.'], ['Yes, French! Our letters convinced me to study it.', 'Oui, le français ! Nos lettres m\'ont convaincue de l\'étudier.'], ['We read a novel by Camus in class and I thought of you.', 'Nous avons lu un roman de Camus en classe et j\'ai pensé à toi.'], ['I passed my first driving lesson without hitting anything.', 'J\'ai réussi ma première leçon de conduite sans rien percuter.'], ['Our debate team reached the regional final.', 'Notre équipe de débat a atteint la finale régionale.'], ['I volunteered at a festival and met a real illustrator.', 'J\'ai fait du bénévolat dans un festival et rencontré une vraie illustratrice.'], ['My grandma is now teaching Harry to draw birds.', 'Ma grand-mère apprend maintenant à Harry à dessiner des oiseaux.'], ['I have been reading poetry in French, slowly, with a dictionary.', 'Je lis de la poésie en français, lentement, avec un dictionnaire.']],
    [['I am applying to art schools and my portfolio is almost ready.', 'Je postule dans des écoles d\'art et mon portfolio est presque prêt.'], ['I had an interview at a university in Edinburgh — terrifying but exciting.', 'J\'ai passé un entretien dans une université à Édimbourg — terrifiant mais passionnant.'], ['Our final exams start in May, so I have a revision timetable on my wall.', 'Nos examens finaux commencent en mai, j\'ai un planning de révisions au mur.'], ['I cannot believe this is my last year of school.', 'Je n\'arrive pas à croire que c\'est ma dernière année de lycée.'], ['We organised a charity concert and raised three hundred pounds.', 'Nous avons organisé un concert caritatif et récolté trois cents livres.'], ['I read your last letter twice, it made my week.', 'J\'ai lu ta dernière lettre deux fois, elle a illuminé ma semaine.'], ['Biscuit is getting old and sleeps even more than before.', 'Biscuit vieillit et dort encore plus qu\'avant.'], ['Priya and I promised to visit each other wherever we study.', 'Priya et moi nous sommes promis de nous rendre visite où que nous étudions.']]
  ];
  var ASK = [['What are you reading at the moment?', 'Que lis-tu en ce moment ?', 'reading'], ['How is your dance class going?', 'Comment se passe ton cours de danse ?', 'danse'], ['How are Cataleya and Elynn?', 'Comment vont Cataleya et Elynn ?', 'amies'], ['Has your dad invented any new pancakes?', 'Ton père a-t-il inventé de nouvelles crêpes ?', 'papa'], ['What do you want to study after the bac?', 'Que veux-tu étudier après le bac ?', 'etudes'], ['How is Moka?', 'Comment va Moka ?', 'moka'], ['What is the hardest subject this year?', 'Quelle est la matière la plus difficile cette année ?', 'matiere'], ['Did Daryl win his last video game revenge?', 'Daryl a-t-il gagné sa dernière revanche aux jeux vidéo ?', 'daryl'], ['What did you do last weekend?', 'Qu\'as-tu fait le week-end dernier ?', 'weekend'], ['Do you still play the guitar?', 'Joues-tu toujours de la guitare ?', 'guitare']];
  var ANS = {
    reading: [['I am reading a classic for my French class and it is surprisingly moving.', 'Je lis un classique pour mon cours de français et c\'est étonnamment émouvant.'], ['A science-fiction novel from the library — I cannot put it down.', 'Un roman de science-fiction du CDI — impossible de le lâcher.']],
    danse: [['Mme Lopez says I have finally mastered my pirouettes!', 'Mme Lopez dit que j\'ai enfin maîtrisé mes pirouettes !'], ['We are rehearsing for the gala; my legs hate me.', 'Nous répétons pour le gala ; mes jambes me détestent.']],
    amies: [['They are great. We still dance together every Tuesday.', 'Elles vont super bien. On danse toujours ensemble le mardi.'], ['Cataleya wrote a song and Elynn grows sunflowers taller than us.', 'Cataleya a écrit une chanson et Elynn fait pousser des tournesols plus grands que nous.']],
    papa: [['He made a pancake shaped like the Eiffel Tower. It collapsed.', 'Il a fait une crêpe en forme de tour Eiffel. Elle s\'est effondrée.'], ['Yes, a Moka-shaped one. Moka was not impressed.', 'Oui, une en forme de Moka. Moka n\'a pas été impressionné.']],
    etudes: [['I would like to study languages, maybe English and Spanish.', 'J\'aimerais étudier les langues, peut-être l\'anglais et l\'espagnol.'], ['Something with journalism or translation, I think.', 'Quelque chose autour du journalisme ou de la traduction, je pense.']],
    moka: [['He is lazy and happy, and he still adores his red ball.', 'Il est paresseux et heureux, et il adore toujours sa balle rouge.'], ['He slept on my homework yesterday, so I had a good excuse.', 'Il a dormi sur mes devoirs hier, j\'avais donc une bonne excuse.']],
    matiere: [['Philosophy: every answer creates three new questions!', 'La philosophie : chaque réponse crée trois nouvelles questions !'], ['Maths, but my dad helps me during his breaks.', 'Les maths, mais mon père m\'aide pendant ses pauses.']],
    daryl: [['No! I am still the champion of the family.', 'Non ! Je reste la championne de la famille.'], ['He won, but only because Moka walked on my controller.', 'Il a gagné, mais seulement parce que Moka a marché sur ma manette.']],
    weekend: [['We had a picnic in the park with my friends and fed the ducks.', 'Nous avons pique-niqué au parc avec mes amies et nourri les canards.'], ['I helped my dad in the garden and we planted tomatoes.', 'J\'ai aidé mon père au jardin et nous avons planté des tomates.']],
    guitare: [['Yes, and I have learnt a new song to play for you one day.', 'Oui, et j\'ai appris une nouvelle chanson pour te la jouer un jour.'], ['Less than before, but it still helps me relax.', 'Moins qu\'avant, mais ça m\'aide toujours à me détendre.']]
  };
  LL.lettreGeneree = function (w) { // w = numéro de semaine (≥ 47)
    var d = LL.LISA_START + (w - 1) * 7, m = LL.md(d)[0] - 1, niv = Math.max(0, Math.min(2, LL.niveauIdx(d) - 2)), k = w - 47;
    var o = OPEN[m], nw = NEWS[niv][k % 8], nw2 = NEWS[niv][(k * 3 + 5) % 8], q = ASK[(k * 7 + 3) % ASK.length]; if (nw2 === nw) nw2 = NEWS[niv][(k + 1) % 8];
    var en = 'Dear Lyham, ' + o[0] + ' ' + nw[0] + ' ' + nw2[0] + ' ' + q[0] + ' Write back soon! Love, Lisa', fr = 'Chère Lyham, ' + o[1] + ' ' + nw[1] + ' ' + nw2[1] + ' ' + q[1] + ' Réponds-moi vite ! Bises, Lisa';
    var a = ANS[q[2]];
    return { id: 'lisa_' + w, n: w, titre: MOIS_EN[m] + ' news', niveau: 'B2', en: en, fr: fr, cond: [], gen: true,
      replies: [{ en: a[0][0], fr: a[0][1], rel: 3 }, { en: a[1][0], fr: a[1][1], rel: 3 }, { en: 'Thanks for your letter. Everything is fine here.', fr: 'Merci pour ta lettre. Tout va bien ici.', rel: 1 }] };
  };
  LL.lettre = function (n) { return n <= LL.LETTRES.length ? LL.LETTRES[n - 1] : LL.lettreGeneree(n); };
  LL.lettresRecues = function () { var s = LL.S; if (s.day < LL.LISA_START) return 0; return Math.min(Math.floor((Math.min(s.day, LL.END_DAY) - LL.LISA_START) / 7) + 1, 1000); };
  /* Phrases de nouvelles personnelles proposées à Lyham, tirées de son vécu réel (journal, liens, drapeaux) */
  LL.nouvellesLyham = function () {
    var s = LL.S, out = [];
    if (s.skills.danse > 30) out.push(['My dance class is going really well; I have improved a lot.', 'Mon cours de danse se passe très bien ; j\'ai beaucoup progressé.']);
    if (s.rel.moka > 70) out.push(['Moka and I are inseparable; he sleeps on my bed every night.', 'Moka et moi sommes inséparables ; il dort sur mon lit chaque nuit.']);
    if (s.rel.casimir > 75) out.push(['My dad and I cooked together this week. He is a great teacher.', 'Mon père et moi avons cuisiné ensemble cette semaine. C\'est un super prof.']);
    if (s.rel.daryl > 65) out.push(['Daryl visited us and we laughed all afternoon.', 'Daryl est venu nous voir et on a ri tout l\'après-midi.']);
    if (s.skills.musique > 25) out.push(['I have learnt a new song on the guitar.', 'J\'ai appris une nouvelle chanson à la guitare.']);
    out.push(['I have a lot of homework, but I am doing my best.', 'J\'ai beaucoup de devoirs, mais je fais de mon mieux.']);
    out.push(['The weather here is ' + { soleil: 'sunny', nuageux: 'cloudy', pluie: 'rainy', neige: 'snowy' }[LL.weather(s.day)] + ' today.', 'Il fait ' + { soleil: 'beau', nuageux: 'nuageux', pluie: 'pluvieux', neige: 'un temps de neige' }[LL.weather(s.day)] + ' aujourd\'hui.']);
    return out.slice(0, 3);
  };
  LL.repondreLisa = function (n, idx, newsIdx) {
    var s = LL.S, l = LL.lettre(n), r = l.replies[idx]; if (!r || s.lisa.replies[l.id] != null) return null;
    s.lisa.replies[l.id] = idx; LL.rel('lisa', r.rel); if (r.flag) s.flags[r.flag] = s.day; LL.xp('anglais', 6 + Math.min(6, Math.floor(n / 8))); LL.xp('ecriture', 2);
    if (newsIdx != null) LL.xp('anglais', 2);
    LL.log('💌 Lyham a répondu à la lettre n°' + n + ' de Lisa'); if (LL.save) LL.save(); return r;
  };
})();
